contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint depositAmount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (depositAmount)); require(depositAmount <= 1000000000000000000000000000000);
        require(depositAmount > 0);
        require(address(this).balance >= depositAmount);

        c.deposit{value: depositAmount}(); if (__ESBMC_reverted()) return;

        uint contractBalanceBefore = address(c).balance;

        bool firstReverted;
        c.withdrawAll(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            firstReverted = true;
        } else {
            firstReverted = false;
        }

        uint contractBalanceAfterFirst = address(c).balance;

        bool secondReverted;
        c.withdrawAll(); bool __rev1 = __ESBMC_reverted(); if (__rev1) {
            secondReverted = true;
        } else {
            secondReverted = false;
        }

        uint contractBalanceAfterSecond = address(c).balance;

        assert(
            !firstReverted &&
            contractBalanceAfterFirst == contractBalanceBefore - depositAmount &&
            !secondReverted &&
            contractBalanceAfterSecond == contractBalanceAfterFirst
        );
    }

    receive() external payable {}
}

