pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {ReentrancyDAO} from "../src/ReentrancyDAO.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    ReentrancyDAO c;

    function setUp() public {
        c = new ReentrancyDAO();
    }

    function _run(uint256 depositAmount) internal {
        depositAmount = bound(depositAmount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(depositAmount > 0);
        vm.assume(address(this).balance >= depositAmount);
        try c.deposit{value: depositAmount}() {} catch { return; }
        uint contractBalanceBefore = address(c).balance;
        bool firstReverted;
        try c.withdrawAll() {
            firstReverted = false;
        } catch {
            firstReverted = true;
        }
        uint contractBalanceAfterFirst = address(c).balance;
        bool secondReverted;
        try c.withdrawAll() {
            secondReverted = false;
        } catch {
            secondReverted = true;
        }
        uint contractBalanceAfterSecond = address(c).balance;
        assertTrue(!firstReverted &&
            contractBalanceAfterFirst == contractBalanceBefore - depositAmount &&
            !secondReverted &&
            contractBalanceAfterSecond == contractBalanceAfterFirst);
    }

    function testFuzz_run(uint256 depositAmount) public {
        _run(depositAmount);
    }

    receive() external payable {}
}
